<div class="page-title"><div><em>ACTIVITY</em><h1>Transactions</h1><p>Search, filter and review your account activity.</p></div><button class="outline">↓ Download statement</button></div><section class="panel"><form class="filter" method="get"><input name="q" value="<?=html_escape($filters['search'])?>" placeholder="⌕ Search transactions"><select name="type"><option value="">All types</option><option value="credit" <?=$filters['type']==='credit'?'selected':''?>>Credits</option><option value="debit" <?=$filters['type']==='debit'?'selected':''?>>Debits</option></select><button class="outline">Filter</button></form><div class="data-table transaction-table"><div class="tr th"><span>Transaction</span><span>Date</span><span>Account</span><span>Amount</span><span>Status</span></div><?php foreach($transactions as $t):?><div class="tr"><span class="name"><i><?=transaction_icon($t['type'])?></i><b><?=html_escape($t['description'])?><small><?=html_escape($t['category'])?></small></b></span><span><?=date('M j, Y',strtotime($t['transaction_date']))?></span><span><?=html_escape($t['account_name'])?> •<?=substr($t['account_number'],-4)?></span><strong class="<?=$t['type']?>"><?=$t['type']==='credit'?'+':'−'?> <?=money($t['amount'],$t['currency'])?></strong><span class="<?=status_class($t['status'])?>"><?=ucfirst($t['status'])?></span></div><?php endforeach?></div></section>
